        string_t blob = FlatVector::GetData<string_t>(in_vec)[i];
        int32_t n_arg = FlatVector::GetData<int32_t>(n_vec)[i];
        Temporal *in = BlobToTemporal(blob);
        int count = 0;
        Span * arr = temporal_split_each_n_spans(in, n_arg, &count);
